from PIL import Image
from collections import Counter
im=Image.open('sheet.png').convert('RGBA');w,h=im.size
for threshold in [16,128,240]:
 a=im.getchannel('A').point(lambda p:255 if p>=threshold else 0);p=a.load();seen=bytearray(w*h);cs=[]
 for y in range(h):
  for x in range(w):
   i=y*w+x
   if seen[i] or not p[x,y]:continue
   seen[i]=1;q=[(x,y)];n=0;x0=x1=x;y0=y1=y
   while q:
    xx,yy=q.pop();n+=1;x0=min(x0,xx);x1=max(x1,xx);y0=min(y0,yy);y1=max(y1,yy)
